  if(!preg_match('/^[a-f0-9]{64}$/',$expectedHash)||$find==='')throw new InvalidArgumentException('An expected SHA-256 and non-empty exact match are required.');if(strlen($find)>262144||strlen($replace)>262144)throw new InvalidArgumentException('Edit strings exceed 256 KB.');$file=$this->path($path);if(!is_file($file))throw new RuntimeException('Edit target is not a file.');$content=file_get_contents($file);if($content===false||strlen($content)>1048576)throw new RuntimeException('Edit target exceeds 1 MB or cannot be read.');$actual=hash('sha256',$content);if(!hash_equals($expectedHash,$actual))throw new RuntimeException('File changed since it was read; refresh before editing.');$count=substr_count($content,$find);if($count!==1)throw new RuntimeException('Exact edit must match one occurrence; found '.$count.'.');$updated=str_replace($find,$replace,$content,$replacements);$tmp=tempnam(dirname($file),'.dcp-edit-');if($tmp===false)throw new RuntimeException('Unable to allocate an atomic edit file.');try{if(file_put_contents($tmp,$updated,LOCK_EX)!==strlen($updated))throw new RuntimeException('Unable to write atomic edit file.');@chmod($tmp,0600);if(!rename($tmp,$file))throw new RuntimeException('Unable to atomically replace the file.');}finally{if(is_file($tmp))@unlink($tmp);}return ['path'=>$path,'replacements'=>$replacements,'old_sha256'=>$actual,'sha256'=>hash('sha256',$updated),'size_bytes'=>strlen($updated),'atomic'=>true];
