 public function search(string $query,string $path='.',int $limit=100):array{if($query===''||strlen($query)>200)throw new InvalidArgumentException('Search query must contain 1–200 bytes.');$base=$path==='.'?realpath($this->root):$this->path($path);if(!is_dir($base))throw new RuntimeException('Search root is not a directory.');$found=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($base,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);foreach($it as $entry){if($entry->isLink())continue;if(str_contains($entry->getFilename(),$query)){$found[]=['path'=>substr($entry->getPathname(),strlen(realpath($this->root))+1),'type'=>$entry->isDir()?'directory':'file','size_bytes'=>$entry->isFile()?$entry->getSize():null];if(count($found)>=$limit)break;}}return ['query'=>$query,'matches'=>$found,'truncated'=>count($found)>=$limit];}
}
